#[derive(Debug, Clone, Copy, Default, PartialEq, Deserialize)]
#[serde(default)]
pub struct WikiWaveDistance {
    pub min_m: f64,
    pub max_m: f64,
}

impl WikiWaveDistance {
    /// Returns a deterministic representative distance in meters within `[min_m, max_m]`.
    pub fn effective_m(self) -> f64 {
        if self.min_m == self.max_m {
            self.min_m
        } else {
            0.5 * (self.min_m + self.max_m)
        }
    }
}

fn deserialize_opt_wave_distance<'de, D>(
    deserializer: D,
) -> Result<Option<WikiWaveDistance>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum RawWaveDistance {
        Range { min_m: f64, max_m: f64 },
        Scalar(f64),
    }
    let opt = Option::<RawWaveDistance>::deserialize(deserializer)?;
    Ok(opt.map(|raw| match raw {
        RawWaveDistance::Range { min_m, max_m } => WikiWaveDistance { min_m, max_m },
        RawWaveDistance::Scalar(v) => WikiWaveDistance { min_m: v, max_m: v },
    }))
}

